277	constexpr int64_t MIN_FULL_N = 64;
278	constexpr int64_t MAX_HADAMARD_N = 16384;
279	constexpr uint32_t AIV_NUM = 40; // vector cores on Atlas A2 (Ascend910B)
280	
281	int64_t FastHadamardDynamicQuantNpu(torch::Tensor& x, int64_t hadamard_n, torch::Tensor& y, torch::Tensor& row_scales)
282	{
283	    TORCH_CHECK(torch_npu::utils::is_npu(x), "x must be on the NPU device");
284	    TORCH_CHECK(torch_npu::utils::is_npu(y), "out must be on the NPU device");
285	    TORCH_CHECK(torch_npu::utils::is_npu(row_scales), "row_scales must be on the NPU device");
286	    TORCH_CHECK(x.scalar_type() == at::kHalf, "x dtype must be float16");
287	    TORCH_CHECK(y.scalar_type() == at::kChar, "out dtype must be int8 (packed int4)");
288	    TORCH_CHECK(row_scales.scalar_type() == at::kFloat, "row_scales dtype must be float32");
289	    TORCH_CHECK(x.is_contiguous() && y.is_contiguous() && row_scales.is_contiguous(),
290	                "x, out, row_scales must be contiguous");
291	    TORCH_CHECK(x.dim() >= 1, "x rank must be >= 1");
292	
293	    const int64_t fullN = x.size(x.dim() - 1);
294	    const int64_t totalElems = x.numel();
295	    TORCH_CHECK(fullN > 0, "last dim fullN must be positive");
296	    TORCH_CHECK(fullN >= MIN_FULL_N && fullN <= MAX_HADAMARD_N && (fullN & (fullN - 1)) == 0, "last dim fullN=", fullN,
297	                " must be a power of two in [", MIN_FULL_N, ", ", MAX_HADAMARD_N, "]");
298	    TORCH_CHECK(totalElems % fullN == 0, "total elements not divisible by fullN");
299	
300	    int64_t hadamardN = (hadamard_n > 0) ? hadamard_n : fullN;
301	    TORCH_CHECK(hadamardN > 1 && hadamardN <= MAX_HADAMARD_N && (hadamardN & (hadamardN - 1)) == 0,
302	                "hadamard_n=", hadamardN, " must be a power of two in (2, ", MAX_HADAMARD_N, "]");
303	    TORCH_CHECK(fullN % hadamardN == 0, "fullN must be a multiple of hadamard_n");
304	
305	    uint32_t logHadamardN = 0;
306	    for (int64_t v = hadamardN; v > 1; v >>= 1) {
307	        ++logHadamardN;
308	    }
309	    const uint32_t batch = static_cast<uint32_t>(totalElems / fullN);
310	    const float invSqrtHadamardN = 1.0f / std::sqrt(static_cast<float>(hadamardN));
311	
312	    uint32_t blockDim = (batch < AIV_NUM) ? batch : AIV_NUM;
313	    if (blockDim == 0) {
314	        blockDim = 1;
315	    }
316	
317	    auto stream = c10_npu::getCurrentNPUStream().stream(false);
318	    at_npu::native::OpCommand::RunOpApi("fast_hadamard_dynamic_quant", [=]() -> int {
319	        FastHadamardDynamicQuantKernelLaunch(blockDim, stream, (uint8_t*)x.data_ptr(), (uint8_t*)y.data_ptr(),
320	                                             (uint8_t*)row_scales.data_ptr(), batch, static_cast<uint32_t>(fullN),
321	                                             static_cast<uint32_t>(hadamardN), logHadamardN, invSqrtHadamardN);
322	        return 0;
323	    });
324	    return 0;
325	}
